local inspection=...=="__inspect"
local E=_G
local T,F,R,Q,W,L={},{},{},{},{},{}
local function pack(...)return {n=select('#',...),...}end
local function newclosure(p,u)
 local body=assert(L[p],"missing recovered native Lua body "..tostring(p))
 return function(...)return body(u,...)end
end
local empty={}
local function unpack_large(t,a,b)
 if b<a then return end
 if b-a<8 then return unpack(t,a,b)end
 return t[a],t[a+1],t[a+2],t[a+3],t[a+4],t[a+5],t[a+6],t[a+7],unpack_large(t,a+8,b)
end
Q[13]=function(first,last,t)
 first=first or 1;last=last or #t
 if last-first+1>7997 then return unpack_large(t,first,last)end
 return unpack(t,first,last)
end
Q[14]=next
Q[19]=function(size)if size>100000 then return {}end;return {}end
Q[22]={}
Q[26]=function(...)return E.bit.bxor(...)end
Q[42]=function(...)local n=select('#',...);if n==0 then return 0,empty end;return n,{...}end
local descriptor_ids={}
Q[45]=function(descriptor,captures)
 local id=assert(descriptor_ids[descriptor],'unknown recovered descriptor')
 local body=assert(F[id],'missing recovered function '..tostring(id))
 return function(...)return body(captures,...)end
end

