R[1336400736][1663]=([=[
    var hud = $.GetContextPanel();
    function local_assist(p, name, depth) {
        if (p === null || depth > 4) return false;
        if (p.text !== undefined && String(p.text).trim() === name) return true;
        for (var i = 0; i < Math.min(p.GetChildCount(), 32); i++)
            if (local_assist(p.GetChild(i), name, depth + 1)) return true;
        return false;
    }
    function set_hidden(hidden) {
        var feed = hud.FindChildTraverse('HudDeathNotice');
        if (feed === null) return;
        var notices = feed.FindChildTraverse('VisibleNotices');
        if (notices === null) return;
        var name = GameStateAPI.GetPlayerName(GameStateAPI.GetLocalPlayerXuid());
        for (var i = 0; i < notices.GetChildCount(); i++) {
            var notice = notices.GetChild(i);
            var assist = notice.FindChildTraverse('AssistParent');
            var own = assist !== null && name && local_assist(assist, name, 0);
            if (hidden && own) {
                if (notice.BHasClass('DeathNotice_Killer')) {
                    notice._persistenceAssistHighlight = true;
                    notice.RemoveClass('DeathNotice_Killer');
                }
            } else if (notice._persistenceAssistHighlight) {
                if (!hidden && own) notice.AddClass('DeathNotice_Killer');
                notice._persistenceAssistHighlight = false;
            }
            if (assist !== null) assist.style.visibility = hidden ? 'collapse' : null;
        }
    }
    return { set_hidden: set_hidden };
]=])

