    var hud = $.GetContextPanel();
    function insert_icon(notice, target_id, icon_path, icon_id, after) {
        if (!icon_path || notice.FindChildTraverse(icon_id) !== null) return;

        var target = notice.FindChildTraverse(target_id);
        if (target === null || target.GetParent() === null) return;

        var parent = target.GetParent();
        var icon = $.CreatePanel('Image', parent, icon_id);
        icon.SetImage(icon_path);
        icon.style.width = '16px';
        icon.style.height = '16px';
        icon.style.marginLeft = after ? '3px' : '0px';
        icon.style.marginRight = after ? '0px' : '3px';
        icon.style.verticalAlign = 'center';
        icon.style.imgShadow = '0px 0px 2px 1.0 #000000aa';

        if (after) parent.MoveChildAfter(icon, target);
        else parent.MoveChildBefore(icon, target);
    }

    function add_icons(attacker_name, victim_name, attacker_icon, victim_icon) {
        var attempts = 0;

        function apply() {
            var feed = hud.FindChildTraverse('HudDeathNotice');
            var notices = feed && feed.FindChildTraverse('VisibleNotices');
            if (notices !== null && notices.GetChildCount() > 0) {
                for (var i = notices.GetChildCount() - 1; i >= 0; i--) {
                    var notice = notices.GetChild(i);
                    var killer = notice.FindChildTraverse('DeathNotice_Killer');
                    var victim = notice.FindChildTraverse('DeathNotice_Victim');
                    var killer_matches = !attacker_icon || (killer !== null && killer.text === attacker_name);
                    var victim_matches = !victim_icon || (victim !== null && victim.text === victim_name);

                    if (killer_matches && victim_matches) {
                        insert_icon(notice, 'DeathNotice_Killer', attacker_icon, 'RevealerKillerIcon', false);
                        insert_icon(notice, 'DeathNotice_Victim', victim_icon, 'RevealerVictimIcon', true);
                        return;
                    }
                }
            }

            if (++attempts < 6) $.Schedule(0.01, apply);
        }

        $.Schedule(0.0, apply);
    }

    function clear_icons() {
        var feed = hud.FindChildTraverse('HudDeathNotice');
        var notices = feed && feed.FindChildTraverse('VisibleNotices');
        if (notices === null) return;

        for (var i = 0; i < notices.GetChildCount(); i++) {
            var notice = notices.GetChild(i);
            var killer = notice.FindChildTraverse('RevealerKillerIcon');
            var victim = notice.FindChildTraverse('RevealerVictimIcon');
            if (killer !== null) killer.DeleteAsync(0.0);
            if (victim !== null) victim.DeleteAsync(0.0);
        }
    }

    return { add_icons: add_icons, clear_icons: clear_icons };
]=])

