R[1336400736][2820]=([=[
sampler2D Background : register(s0);
float4 capture : register(c0); // xy = capture origin, zw = inverse capture size
float4 panel : register(c1);   // xy = panel origin, zw = size
float4 style : register(c2);   // radius, glow weight, dark tint, opacity
float4 refractParams : register(c3); // powerFactor, a, b, d
float4 finish : register(c4);  // c, fPower, noise, glowBias
float4 glowEdges : register(c5);
float4 projection0 : register(c9);
float4 projection1 : register(c10);
float4 projection2 : register(c11);
float4 edgeColor : register(c12);

float sdRoundedPanel(float2 p) {
    // Requested rounding: 99 px, clamped to half the panel's smaller side.
    float2 halfSize = panel.zw * 0.5;
    float radius = min(glowEdges.w>0 ? glowEdges.w : 99.0, min(halfSize.x, halfSize.y));
    float2 q = abs(p * halfSize) - (halfSize - radius);
    return (length(max(q,0.0)) + min(max(q.x,q.y),0.0) - radius) / halfSize.y;
}
float refractionFunc(float x) {
    return 1.0 - refractParams.z * pow(max(finish.x,0.00001) * 2.718281828459045,
        -refractParams.w * x - refractParams.y);
}
float rand(float2 co) { return frac(sin(dot(co,float2(12.9898,78.233))) * 43758.5453); }
float Glow(float2 uv) {
    float2 v=uv*2-1;
    return dot(v,float2(-0.479425539,0.877582562))*rsqrt(max(dot(v,v),1e-8));
}

// Nine bilinear samples; spacing approximates the old kernel's variance.
float3 blur9(float2 uv) {
    [branch] if(style.x<=0.001) return tex2Dlod(Background,float4(uv,0,0)).rgb;
    float2 delta=capture.zw*style.x*2.754;
    float2 dx=float2(delta.x,0),dy=float2(0,delta.y);
    float3 result=tex2Dlod(Background,float4(uv,0,0)).rgb*0.25;
    result+=(tex2Dlod(Background,float4(uv+dx,0,0)).rgb+tex2Dlod(Background,float4(uv-dx,0,0)).rgb+
             tex2Dlod(Background,float4(uv+dy,0,0)).rgb+tex2Dlod(Background,float4(uv-dy,0,0)).rgb)*0.125;
    result+=(tex2Dlod(Background,float4(uv+dx+dy,0,0)).rgb+tex2Dlod(Background,float4(uv+dx-dy,0,0)).rgb+
             tex2Dlod(Background,float4(uv-dx+dy,0,0)).rgb+tex2Dlod(Background,float4(uv-dx-dy,0,0)).rgb)*0.0625;
    return result;
}
float4 main(float2 uv : TEXCOORD0) : COLOR0 {
    float2 p = (uv-0.5)*2;
    float d = sdRoundedPanel(p);
    float aa = max(fwidth(d),0.0001);
    float2 pixelX = ddx(p) * 0.25;
    float2 pixelY = ddy(p) * 0.25;
    float coverage=saturate(0.5-d/aa);
    [branch] if(abs(d)<aa) coverage = 0.25 * (
        saturate(0.5-sdRoundedPanel(p-pixelX-pixelY)/aa) +
        saturate(0.5-sdRoundedPanel(p+pixelX-pixelY)/aa) +
        saturate(0.5-sdRoundedPanel(p-pixelX+pixelY)/aa) +
        saturate(0.5-sdRoundedPanel(p+pixelX+pixelY)/aa));
    clip(coverage-0.001);
    float dist = max(-d,0);
    float2 sampleP = p * pow(max(refractionFunc(dist),0.001),finish.y);
    // XYZRHW vertices use top-left screen coordinates; no NDC Y flip required.
    float2 sampleScreen = panel.xy + (sampleP*0.5+0.5)*panel.zw;
    if(glowEdges.z>0.5) {
        float3 localPoint=float3(sampleP*0.5+0.5,1);
        float divisor=max(dot(projection2.xyz,localPoint),0.001);
        sampleScreen=float2(dot(projection0.xyz,localPoint),dot(projection1.xyz,localPoint))/divisor;
    }
    float2 coord = (sampleScreen - capture.xy) * capture.zw;
    float3 result = blur9(coord);
    // Keep the grain stable while panels move through fractional pixels.
    result += (rand(floor(panel.xy+uv*panel.zw)*0.001)-0.5)*finish.z;
    float glow = Glow(uv)*style.y*smoothstep(glowEdges.x,glowEdges.y,dist)+1+finish.w;
    result *= glow;
    result = lerp(result,float3(0.025,0.038,0.065),style.z);
    float edge=1-smoothstep(0.0,max(aa*1.4,0.001),dist);
    result=lerp(result,edgeColor.rgb,edgeColor.a*edge);
    return float4(saturate(result),coverage*style.w);
}
]=])

